BASES = "TCAG"
AMINO = "FFLLSSSSYY**CC*WLLLLPPPPHHQQRRRRIIIMTTTTNNKKSSRRVVVVAAAADDEEGGGG"
CODE = {a + b + c: AMINO[16 * i + 4 * j + k]
        for i, a in enumerate(BASES) for j, b in enumerate(BASES) for k, c in enumerate(BASES)}

def first_protein(dna):
    """Translate from the first ATG to the first in-frame stop codon."""
    dna = dna.upper()
    start = dna.find("ATG")
    if start < 0:
        return ""
    protein = []
    for i in range(start, len(dna) - 2, 3):
        aa = CODE[dna[i:i + 3]]
        if aa == "*":
            break
        protein.append(aa)
    return "".join(protein)
